input_grid = [
    [6, 0, 6, 6, 6, 6, 6, 0, 6, 6, 6],
    [6, 0, 6, 0, 0, 0, 6, 0, 6, 0, 0],
    [6, 6, 6, 0, 6, 0, 6, 0, 6, 6, 6],
    [6, 0, 0, 0, 6, 0, 6, 7, 2, 7, 6],
    [6, 6, 6, 6, 6, 0, 6, 6, 6, 6, 6]
]

# Inverse transform (swap 0 and 6)
output = []
for row in input_grid:
    new_row = []
    for val in row:
        if val == 6:
            new_row.append(0)
        elif val == 0:
            new_row.append(6)
        else:
            new_row.append(val)
    output.append(new_row)

print("Submitting inverse transform:")
for row in output:
    print(row)

